sp_widget.css:
.quick-links-section {
  width: 86%;
  max-width: 1200px;
  margin: 0 auto 50px;

  font-family: Arial, sans-serif;
}

.quick-links-content {
  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 25px 30px;

  background: #f8fafc;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

.quick-links-content h3 {
  margin: 0 0 7px;
  color: #111827;
  font-size: 18px;
}

.quick-links-content p {
  margin: 0;
  color: #6b7280;
  font-size: 13px;
}

.quick-links-buttons {
  display: flex;
  gap: 12px;
}

.ql-btn {
  padding: 11px 18px;

  background: #ffffff;
  color: #374151;

  border: 1px solid #d1d5db;
  border-radius: 7px;

  font-size: 13px;
  font-weight: 600;

  cursor: pointer;
}

.ql-btn .glyphicon {
  margin-right: 6px;
}

.ql-btn.primary {
  background: #2563eb;
  color: #ffffff;
  border-color: #2563eb;
}

.ql-btn:hover {
  opacity: 0.9;
}

@media (max-width: 768px) {

  .quick-links-section {
    width: 90%;
  }

  .quick-links-content {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;

    padding: 22px;
  }

  .quick-links-buttons {
    width: 100%;
    flex-direction: column;
  }

  .ql-btn {
    width: 100%;
  }
}
